import math, json, collections, statistics

def num_objects(scope):
    objects = entities(doc, scope)
    return len(objects)

def num_events(scope):
    return len(outcomes(doc, scope))

def motion_rows_count(scope):
    scope_node = node_by_title(doc, scope)
    motion_node = None
    for cid in scope_node.get("children", []):
        child = node_by_id(doc, cid)
        if child["kind"] == "table" and child["title"].endswith(": Motion log"):
            motion_node = child
            break
    if motion_node:
        return len(table_rows(motion_node))
    return 0

