import math

def _radius(shape: str) -> float:
    if shape == "cube":
        return 0.5
    if shape == "sphere":
        return 0.5
    if shape == "cylinder":
        return 0.25
    return 0.5

def _mass(material: str) -> float:
    return 2.0 if material == "metal" else 1.0

def _collision_time(p1, v1, r1, p2, v2, r2, dt):
    d0 = (p1[0]-p2[0], p1[1]-p2[1])
    dv = (v1[0]-v2[0], v1[1]-v2[1])
    a = dv[0]*dv[0] + dv[1]*dv[1]
    b = 2*(d0[0]*dv[0] + d0[1]*dv[1])
    c = d0[0]*d0[0] + d0[1]*d0[1] - (r1+r2)*(r1+r2)
    if a == 0:
        return 0.0 if c <= 0 else None
    disc = b*b - 4*a*c
    if disc < 0:
        return None
    sqrt_disc = math.sqrt(disc)
    t1 = (-b - sqrt_disc) / (2*a)
    t2 = (-b + sqrt_disc) / (2*a)
    if t1 >= 0 and t1 <= dt:
        return t1
    if t2 >= 0 and t2 <= dt:
        return t2
    return None

def _elastic_collision(va, vb, ma, mb, pa, pb):
    if ma == mb:
        return vb, va
    n = ((pa[0]-pb[0]), (pa[1]-pb[1]))
    dist = math.hypot(n[0], n[1])
    if dist == 0:
        return va, vb
    n = (n[0]/dist, n[1]/dist)
    p = 2*(va[0]*n[0] + va[1]*n[1] - vb[0]*n[0] - vb[1]*n[1]) / (ma+mb)
    new_va = (va[0]-p*ma*n[0], va[1]-p*ma*n[1])
    new_vb = (vb[0]+p*mb*n[0], vb[1]+p*mb*n[1])
    return new_va, new_vb

