import math
from typing import Dict, List, Tuple, Any

# ------------------------------------------------------------------ physics helpers ---------------------------------------

def _radius(shape: str) -> float:
    if shape == "cube":
        return 0.5
    if shape == "sphere":
        return 0.5
    if shape == "cylinder":
        return 0.25
    return 0.5

def _mass(material: str) -> float:
    return 2.0 if material == "metal" else 1.0

def _collision_time(p1, v1, r1, p2, v2, r2, dt):
    """Return earliest collision time in (0, dt] if any, else None."""
    d0 = (p1[0]-p2[0], p1[1]-p2[1])
    dv = (v1[0]-v2[0], v1[1]-v2[1])
    a = dv[0]*dv[0] + dv[1]*dv[1]
    b = 2*(d0[0]*dv[0] + d0[1]*dv[1])
    c = d0[0]*d0[0] + d0[1]*d0[1] - (r1+r2)*(r1+r2)
    if a == 0:
        return 0.0 if c <= 0 else None
    disc = b*b - 4*a*c
    if disc < 0:
        return None
    sqrt_disc = math.sqrt(disc)
    t1 = (-b - sqrt_disc) / (2*a)
    t2 = (-b + sqrt_disc) / (2*a)
    if t1 >= 0 and t1 <= dt:
        return t1
    if t2 >= 0 and t2 <= dt:
        return t2
    return None

def _elastic_collision(va, vb, ma, mb, pa, pb):
    """Return new velocities after perfect elastic collision for 2D."""
    if ma == mb:
        return vb, va
    n = ((pa[0]-pb[0]), (pa[1]-pb[1]))
    dist = math.hypot(n[0], n[1])
    if dist == 0:
        return va, vb
    n = (n[0]/dist, n[1]/dist)
    p = 2*(va[0]*n[0] + va[1]*n[1] - vb[0]*n[0] - vb[1]*n[1]) / (ma+mb)
    new_va = (va[0]-p*ma*n[0], va[1]-p*ma*n[1])
    new_vb = (vb[0]+p*mb*n[0], vb[1]+p*mb*n[1])
    return new_va, new_vb

# ------------------------------------------------------------------ main simulation ---------------------------------------

def simulate(doc: Dict, scope: str, inputs: List[Dict[str, Any]],
             params: Dict[str, Any], start: float = None,
             horizon: float = None) -> List[Dict[str, Any]]:

    # Locate motion log
    scope_node = node_by_title(doc, scope)
    motion_node = None
    for cid in scope_node.get("children", []):
        child = node_by_id(doc, cid)
        if child["kind"] == "table" and child["title"].endswith(": Motion log"):
            motion_node = child
            break

    # Build per‑object motion record
    motion_by_obj: Dict[str, List[Tuple[float, Tuple[float,float], Tuple[float,float]]]] = {}
    if motion_node:
        for _, row in table_rows(motion_node):
            try:
                f = float(row["frame"])
                obj_field = row["object"]  # e.g., "1 green rubber sphere"
                oid_num = re.match(r"(\d+)", obj_field).group(1)
                oid = f"Object {oid_num}"
            except Exception:
                continue
            pos = (float(row["x"]), float(row["y"]))
            vel = (float(row["vx"]), float(row["vy"]))
            motion_by_obj.setdefault(oid, []).append((f, pos, vel))
    for lst in motion_by_obj.values():
        lst.sort(key=lambda x: x[0])

    # Determine horizon if not given
    all_frames = [f for lst in motion_by_obj.values() for f,_,_ in lst]
    recorded_end = max(all_frames) if all_frames else None
    if horizon is None:
        horizon = recorded_end if recorded_end is not None else start
    if horizon is None:
        return []

    if start is None:
        start = min([inp["time"] for inp in inputs]) if inputs else 0.0

    # Map object -> description
    entity_desc: Dict[str, Dict[str, str]] = {}
    for node in doc["nodes"]:
        if node["kind"] == "list" and node["title"].endswith(": Objects"):
            for line in node["lines"]:
                m = re.match(r"(Object \d+):\s*(.+)", line)
                if m:
                    oid, desc = m.groups()
                    shape = re.search(r'shape=([^\s,]+)', desc).group(1)
                    material = re.search(r'material=([^\s,]+)', desc).group(1)
                    entity_desc[oid] = {"shape": shape, "material": material}

    # Initialise state from earliest inputs
    state: Dict[str, Dict[str, Any]] = {}
    for inp in inputs:
        if inp["time"] <= start:
            oid = inp["entities"][0]
            recs = motion_by_obj.get(oid, [])
            if not recs:
                continue
            pos, vel = recs[0][1], recs[0][2]
            for f,p,v in recs:
                if f > inp["time"]:
                    break
                pos, vel = p, v
            info = entity_desc.get(oid, {"shape":"sphere","material":"rubber"})
            state[oid] = {"pos":pos[:], "vel":vel[:], "exists":True,
                          "shape": info["shape"], "material": info["material"],
                          "radius": _radius(info["shape"]),
                          "mass": _mass(info["material"]),
                          "last_frame": recs[-1][0]}

    # Compute exit times (last frame per object)
    exit_times: Dict[str, float] = {oid: recs[-1][0] for oid, recs in motion_by_obj.items()}

    # Build timeline
    timeline = sorted(set([start] + [inp["time"] for inp in inputs] + ([horizon] if horizon is not None else [])))
    if timeline[0] != start:
        timeline = [start] + timeline
    outcomes: List[Dict[str, Any]] = []
    current_time = start

    # Helper: deduplicate collision events
    last_coll = None

    while current_time < horizon:
        # Identify next event time (inputs or exit or horizon)
        next_time = horizon
        for t in timeline:
            if t > current_time:
                next_time = t
                break
        # Also consider exit times ahead of next_time
        future_exits = [(et, oid) for oid, et in exit_times.items() if state.get(oid) and et > current_time and et < next_time]
        if future_exits:
            et, oid = min(future_exits)
            next_time = et

        dt = next_time - current_time
        # Event‑driven simulation in dt
        while dt > 1e-8:
            oids = [oid for oid, st in state.items() if st["exists"]]
            earliest_t = None
            coll_pair = None
            for i in range(len(oids)):
                for j in range(i+1, len(oids)):
                    a,b = oids[i], oids[j]
                    ra = state[a]["radius"]; rb = state[b]["radius"]
                    pa = state[a]["pos"]; pb = state[b]["pos"]
                    va = state[a]["vel"]; vb = state[b]["vel"]
                    rel_speed = math.hypot(va[0]-vb[0], va[1]-vb[1])
                    if rel_speed < 0.1:
                        continue  # ignore near‑stationary pairs
                    t_c = _collision_time(pa, va, ra, pb, vb, rb, dt)
                    if t_c is not None and (earliest_t is None or t_c < earliest_t):
                        earliest_t = t_c
                        coll_pair = (a,b)
            if earliest_t is not None and earliest_t > 0:
                # Advance all
                for oid in oids:
                    st = state[oid]
                    st["pos"] = (st["pos"][0] + st["vel"][0]*earliest_t,
                                 st["pos"][1] + st["vel"][1]*earliest_t)
                current_time += earliest_t
                dt -= earliest_t
                a,b = coll_pair
                ma = state[a]["mass"]; mb = state[b]["mass"]
                va = state[a]["vel"]; vb = state[b]["vel"]
                pa = state[a]["pos"]; pb = state[b]["pos"]
                new_va, new_vb = _elastic_collision(va, vb, ma, mb, pa, pb)
                state[a]["vel"], state[b]["vel"] = new_va, new_vb
                # Deduplicate close collisions
                if last_coll is None or abs(last_coll["time"] - current_time) > 1e-4 or set(last_coll["entities"]) != set([a,b]):
                    outcomes.append({"time": current_time, "kind":"collision",
                                     "entities":[a,b], "value":None, "src":[]})
                    last_coll = last_coll if last_coll else {"time": current_time, "entities":[a,b]}
                else:
                    # skip duplicate
                    pass
            else:
                # no collision in remaining dt
                for oid in oids:
                    st = state[oid]
                    st["pos"] = (st["pos"][0] + st["vel"][0]*dt,
                                 st["pos"][1] + st["vel"][1]*dt)
                current_time += dt
                dt = 0

        # Process inputs at current_time
        for inp in inputs:
            if abs(inp["time"] - current_time) < 1e-8:
                oid = inp["entities"][0]
                if inp["kind"] in ("present", "enter"):
                    if oid in state and state[oid]["exists"]:
                        continue
                    recs = motion_by_obj.get(oid, [])
                    if recs:
                        pos, vel = recs[0][1], recs[0][2]
                        for f,p,v in recs:
                            if f > inp["time"]:
                                break
                            pos, vel = p, v
                    else:
                        pos, vel = (0.0,0.0),(0.0,0.0)
                    info = entity_desc.get(oid, {"shape":"sphere","material":"rubber"})
                    state[oid] = {"pos":pos[:], "vel":vel[:], "exists":True,
                                  "shape": info["shape"], "material": info["material"],
                                  "radius": _radius(info["shape"]),
                                  "mass": _mass(info["material"]),
                                  "last_frame": recs[-1][0] if recs else current_time}

        # Process exits that occur at current_time
        for oid, et in exit_times.items():
            if state.get(oid) and state[oid]["exists"] and abs(et - current_time) < 1e-8:
                outcomes.append({"time": et, "kind":"exit",
                                 "entities":[oid], "value":None, "src":[]})
                state[oid]["exists"] = False

    # Return outcomes after original start
    outcomes = [o for o in outcomes if o["time"] > start]
    return sorted(outcomes, key=lambda o: o["time"])

