        for _, row in table_rows(motion_node):
            try:
                f = float(row["frame"])
                obj_field = row["object"]
                oid_num = re.match(r"(\d+)", obj_field).group(1)
                oid = f"Object {oid_num}"
            except Exception:
                continue
            pos = (float(row["x"]), float(row["y"]))
            vel = (float(row["vx"]), float(row["vy"]))
            motion_by_obj.setdefault(oid, []).append((f, pos, vel))
    for lst in motion_by_obj.values():
        lst.sort(key=lambda x: x[0])

    # Determine horizon if not given
    all_frames = [f for lst in motion_by_obj.values() for f,_,_ in lst]
    recorded_end = max(all_frames) if all_frames else None
    if horizon is None:
        horizon = recorded_end if recorded_end is not None else start
    if horizon is None:
        return []

    if start is None:
        start = min([inp["time"] for inp in inputs]) if inputs else 0.0

    # Map object -> description
    entity_desc: Dict[str, Dict[str, str]] = {}
    for node in doc["nodes"]:
        if node["kind"] == "list" and node["title"].endswith(": Objects"):
            for line in node["lines"]:
                m = re.match(r"(Object \d+):\s*(.+)", line)
                if m:
                    oid, desc = m.groups()
                    shape = re.search(r'shape=([^\s,]+)', desc).group(1)
                    material = re.search(r'material=([^\s,]+)', desc).group(1)
                    entity_desc[oid] = {"shape": shape, "material": material}

    # Initialise state from earliest inputs
    state: Dict[str, Dict[str, Any]] = {}
    for inp in inputs:
        if inp["time"] <= start:
            oid = inp["entities"][0]
            recs = motion_by_obj.get(oid, [])
            if not recs:
                continue
            pos, vel = recs[0][1], recs[0][2]
            for f,p,v in recs:
                if f > inp["time"]:
                    break
                pos, vel = p, v
            info = entity_desc.get(oid, {"shape":"sphere","material":"rubber"})
            state[oid] = {"pos":pos[:], "vel":vel[:], "exists":True,
                          "shape": info["shape"], "material": info["material"],
                          "radius": _radius(info["shape"]),
                          "mass": _mass(info["material"]),
                          "last_frame": recs[-1][0]}

    # Compute exit times (last recorded frame per object)
    exit_times: Dict[str, float] = {oid: recs[-1][0] for oid, recs in motion_by_obj.items()}

    # Build timeline with input times, horizon and exit times
    timeline = sorted(set([start] + [inp["time"] for inp in inputs]
                          + ([horizon] if horizon is not None else [])))
    # Ensure exit times are included
    for et in exit_times.values():
        if start < et < horizon:
            timeline.append(et)
    timeline = sorted(set(timeline))
    if timeline[0] != start:
        timeline = [start] + timeline

    outcomes: List[Dict[str, Any]] = []
    current_time = start

    # Helper: avoid duplicate collision event close in time
    def dedup_coll(c_time, e1, e2):
        for o in outcomes:
            if o["kind"] == "collision" and abs(o["time"] - c_time) < 1e-4:
                if set(o["entities"]) == set([e1, e2]):
                    return True
        return False

    while current_time < horizon:
        next_time = horizon
        for t in timeline:
            if t > current_time:
                next_time = t
                break
        dt = next_time - current_time

        # event‑driven within dt
        while dt > 1e-8:
            oids = [oid for oid, st in state.items() if st["exists"]]
            earliest_t = None
            coll_pair = None
            for i in range(len(oids)):
                for j in range(i+1, len(oids)):
                    a,b = oids[i], oids[j]
                    ra = state[a]["radius"]; rb = state[b]["radius"]
                    pa = state[a]["pos"]; pb = state[b]["pos"]
                    va = state[a]["vel"]; vb = state[b]["vel"]
                    t_c = _collision_time(pa, va, ra, pb, vb, rb, dt)
                    if t_c is not None and (earliest_t is None or t_c < earliest_t):
                        earliest_t = t_c
                        coll_pair = (a,b)
            if earliest_t is not None and earliest_t > 0:
                # advance all
                for oid in oids:
                    st = state[oid]
                    st["pos"] = (st["pos"][0] + st["vel"][0]*earliest_t,
                                 st["pos"][1] + st["vel"][1]*earliest_t)
                current_time += earliest_t
                dt -= earliest_t
                a,b = coll_pair
                ma = state[a]["mass"]; mb = state[b]["mass"]
                va = state[a]["vel"]; vb = state[b]["vel"]
                pa = state[a]["pos"]; pb = state[b]["pos"]
                new_va, new_vb = _elastic_collision(va, vb, ma, mb, pa, pb)
                state[a]["vel"], state[b]["vel"] = new_va, new_vb
                if not dedup_coll(current_time, a, b):
                    outcomes.append({"time": current_time, "kind":"collision",
                                     "entities":[a,b], "value":None, "src":[]})
            else:
                # no collision in remaining dt
                for oid in oids:
                    st = state[oid]
                    st["pos"] = (st["pos"][0] + st["vel"][0]*dt,
                                 st["pos"][1] + st["vel"][1]*dt)
                current_time += dt
                dt = 0

        # Process inputs at current_time
        for inp in inputs:
            if abs(inp["time"] - current_time) < 1e-8:
                oid = inp["entities"][0]
                if inp["kind"] in ("present", "enter"):
                    if oid in state and state[oid]["exists"]:
                        continue
                    recs = motion_by_obj.get(oid, [])
                    if recs:
                        pos, vel = recs[0][1], recs[0][2]
                        for f,p,v in recs:
                            if f > inp["time"]:
                                break
                            pos, vel = p, v
                    else:
                        pos, vel = (0.0,0.0),(0.0,0.0)
                    info = entity_desc.get(oid, {"shape":"sphere","material":"rubber"})
                    state[oid] = {"pos":pos[:], "vel":vel[:], "exists":True,
                                  "shape": info["shape"], "material": info["material"],
                                  "radius": _radius(info["shape"]),
                                  "mass": _mass(info["material"]),
                                  "last_frame": recs[-1][0] if recs else current_time}

        # Process exits that occur at current_time
        for oid, et in exit_times.items():
            if state.get(oid) and state[oid]["exists"] and abs(et - current_time) < 1e-8:
                outcomes.append({"time": et, "kind":"exit",
                                 "entities":[oid], "value":None, "src":[]})
                state[oid]["exists"] = False

        # Advance to next_time
        current_time = next_time

    # Add any missing exit events that were after the last simulated tick
    produced_exits = {o["entities"][0] for o in outcomes if o["kind"] == "exit"}
    for oid, et in exit_times.items():
        if start < et <= horizon and oid not in produced_exits:
            outcomes.append({"time": et, "kind":"exit",
                             "entities":[oid], "value":None, "src":[]})

    # Keep only outcomes after start
    outcomes = [o for o in outcomes if o["time"] > start]
    return sorted(outcomes, key=lambda o: o["time"])

import re
from typing import List, Dict, Any, Tuple

# ------------------------------------------------------------------ helper wrappers
def node_by_title(doc: Dict[str, Any], title: str) -> Dict[str, Any]:
    for node in doc["nodes"]:
        if node["title"] == title:
            return node
    raise KeyError(f"Node with title {title!r} not found")

def node_by_id(doc: Dict[str, Any], node_id: str) -> Dict[str, Any]:
    for node in doc["nodes"]:
        if node["node_id"] == node_id:
            return node
    raise KeyError(f"Node with id {node_id!r} not found")

def children(doc: Dict[str, Any], node: Dict[str, Any]) -> List[Dict[str, Any]]:
    return [node_by_id(doc, cid) for cid in node.get("children", [])]

def table_rows(node: Dict[str, Any]) -> List[Tuple[int, Dict[str, str]]]:
    """
    Return a list of (row_index, dict_of_columns) for a table node.
    """
    if node["kind"] != "table":
        return []
    cols = node["table"]["columns"]
    rows = node["table"]["rows"]
    result = []
    for idx, r in enumerate(rows):
        row_dict = {col: cell for col, cell in zip(cols, r)}
        result.append((idx, row_dict))
    return result

# ------------------------------------------------------------------ main functions
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Return a list of entity descriptors (objects) for the given scope."""
    scope_node = node_by_title(doc, scope)
    obj_node = None
    # find the "Objects" list under the scope
    for cid in scope_node.get("children", []):
        child = node_by_id(doc, cid)
        if child["kind"] == "list" and child["title"].endswith(": Objects"):
            obj_node = child
            break
    if obj_node is None:
        return []

    result = []
    for line_idx, line in enumerate(obj_node["lines"]):
        m = re.match(r"(Object \d+):\s*(.+)", line)
        if m:
            obj_id, _desc = m.groups()
            result.append({"id": obj_id, "description": line})
    return result


def recorded_end(doc: Dict[str, Any], scope: str) -> float | None:
    """Return the last frame number recorded in the scope (None if no data)."""
    scope_node = node_by_title(doc, scope)
    motion_node = None
    # find motion log table under the scope
    for cid in scope_node.get("children", []):
        child = node_by_id(doc, cid)
        if child["kind"] == "table" and child["title"].endswith(": Motion log"):
            motion_node = child
            break
    if motion_node is None:
        return None

    max_frame = None
    for _, row in table_rows(motion_node):
        try:
            f = int(row["frame"])
        except (KeyError, ValueError):
            continue
        if max_frame is None or f > max_frame:
            max_frame = f
    return float(max_frame) if max_frame is not None else None


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all external inputs for the given scope."""
    scope_node = node_by_title(doc, scope)
    events_node = None
    # find Events list
    for cid in scope_node.get("children", []):
        child = node_by_id(doc, cid)
        if child["kind"] == "list" and child["title"].endswith(": Events"):
            events_node = child
            break
    if events_node is None:
        return []

    ins = []
    for line_idx, line in enumerate(events_node["lines"]):
        m = re.match(r"Frame (\d+):\s*(.+)", line)
        if not m:
            continue
        frame, rest = m.groups()
        frame_num = float(frame)

        # check for entering or beginning view
        if "enters the scene" in rest:
            obj_m = re.search(r"Object (\d+)", rest)
            if not obj_m:
                continue
            obj_id = f"Object {obj_m.group(1)}"
            ins.append({
                "id": f"in-{obj_id}-{frame}",
                "time": frame_num,
                "kind": "enter",
                "entities": [obj_id],
                "fields": {},
                "src": [[events_node["node_id"], line_idx]]
            })
        elif "is in view when the video begins" in rest:
            obj_m = re.search(r"Object (\d+)", rest)
            if not obj_m:
                continue
            obj_id = f"Object {obj_m.group(1)}"
            ins.append({
                "id": f"present-{obj_id}-{frame}",
                "time": frame_num,
                "kind": "present",
                "entities": [obj_id],
                "fields": {},
                "src": [[events_node["node_id"], line_idx]]
            })
        # other lines (like collisions) are not inputs
    return ins


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all recorded outcomes for the given scope."""
    scope_node = node_by_title(doc, scope)
    events_node = None
    # find Events list
    for cid in scope_node.get("children", []):
        child = node_by_id(doc, cid)
        if child["kind"] == "list" and child["title"].endswith(": Events"):
            events_node = child
            break
    if events_node is None:
        return []

    outs = []
    for line_idx, line in enumerate(events_node["lines"]):
        m = re.match(r"Frame (\d+):\s*(.+)", line)
        if not m:
            continue
        frame, rest = m.groups()
        frame_num = float(frame)

        if "collides with" in rest:
            m_obj = re.findall(r"Object (\d+)", rest)
            if len(m_obj) >= 2:
                objs = [f"Object {i}" for i in m_obj[:2]]
                outs.append({
                    "time": frame_num,
                    "kind": "collision",
                    "entities": objs,
                    "value": None,
                    "src": [[events_node["node_id"], line_idx]]
                })
        elif "exits the scene" in rest:
            m_obj = re.search(r"Object (\d+)", rest)
            if m_obj:
                obj_id = f"Object {m_obj.group(1)}"
                outs.append({
                    "time": frame_num,
                    "kind": "exit",
                    "entities": [obj_id],
                    "value": None,
                    "src": [[events_node["node_id"], line_idx]]
                })
    return outs


def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Return any document‑defined constants (none in this dataset)."""
    return {}


