import math
from typing import Dict, List, Tuple, Any

# ------------------------------------------------------------------ helpers ---------------------------------------

def _radius(shape: str) -> float:
    if shape == "cube":
        return 0.5
    if shape == "sphere":
        return 0.5
    if shape == "cylinder":
        return 0.25
    return 0.5

def _read_motion(doc: Dict, scope: str):
    """Return per-object list of (frame, x, y)."""
    scope_node = node_by_title(doc, scope)
    motion_node = None
    for cid in scope_node.get("children", []):
        child = node_by_id(doc, cid)
        if child["kind"] == "table" and child["title"].endswith(": Motion log"):
            motion_node = child
            break
    motion_by_obj = {}
    if motion_node:
        for _, row in table_rows(motion_node):
            try:
                f = float(row["frame"])
                obj_field = row["object"]
                oid_num = re.match(r"(\d+)", obj_field).group(1)
                oid = f"Object {oid_num}"
            except Exception:
                continue
            pos = (float(row["x"]), float(row["y"]))
            motion_by_obj.setdefault(oid, []).append((f, pos))
    for lst in motion_by_obj.values():
        lst.sort(key=lambda x: x[0])
    return motion_by_obj

def _interpolate_pos(intervals: List[Tuple[float, Tuple[float,float]]], t: float):
    if not intervals:
        return (0.0, 0.0)
    if t <= intervals[0][0]:
        return intervals[0][1]
    if t >= intervals[-1][0]:
        return intervals[-1][1]
    for i in range(len(intervals)-1):
        f0, p0 = intervals[i]
        f1, p1 = intervals[i+1]
        if f0 <= t <= f1:
            dt = t - f0
            if f1 - f0 == 0:
                return p0
            ratio = dt / (f1 - f0)
            return (p0[0] + (p1[0]-p0[0])*ratio, p0[1] + (p1[1]-p0[1])*ratio)
    return intervals[-1][1]

# ------------------------------------------------------------------ main simulation ---------------------------------------

def simulate(doc: Dict, scope: str, inputs: List[Dict[str, Any]],
             params: Dict[str, Any], start: float = None,
             horizon: float = None) -> List[Dict[str, Any]]:

    motion_by_obj = _read_motion(doc, scope)

    # entity descriptions for radii
    entity_desc = {}
    for node in doc["nodes"]:
        if node["kind"] == "list" and node["title"].endswith(": Objects"):
            for line in node["lines"]:
                m = re.match(r"(Object \d+):\s*(.+)", line)
                if m:
                    oid, desc = m.groups()
                    shape = re.search(r'shape=([^\s,]+)', desc).group(1)
                    entity_desc[oid] = {"shape": shape}

    # Determine requested horizon
    all_frames = [f for lst in motion_by_obj.values() for f, _ in lst]
    recorded_end = max(all_frames) if all_frames else None
    if horizon is None:
        horizon = recorded_end if recorded_end is not None else start
    if horizon is None:
        return []
    if start is None:
        start = min([inp["time"] for inp in inputs]) if inputs else 0.0

    outcomes = []

    # Compute exits
    exits = []
    for oid, recs in motion_by_obj.items():
        exit_time = recs[-1][0]
        if exit_time > start:
            exits.append({"time": exit_time, "kind": "exit",
                        "entities": [oid], "value": None, "src": []})

    # Helper to test exist time window
    def exists_before(oid, t):
        recs = motion_by_obj.get(oid, [])
        if not recs:
            return False
        return recs[0][0] <= t <= recs[-1][0]

    # For each pair, find first collision time after start
    oids = list(motion_by_obj.keys())
    for i in range(len(oids)):
        for j in range(i+1, len(oids)):
            a, b = oids[i], oids[j]
            ra = _radius(entity_desc[a]["shape"])
            rb = _radius(entity_desc[b]["shape"])
            threshold = ra + rb
            # Loop over integer frames between start and horizon
            first_frame = int(math.ceil(start))
            last_frame = int(math.floor(horizon))
            collision_time = None
            for f in range(first_frame, last_frame+1):
                if not (exists_before(a, f) and exists_before(b, f)):
                    continue
                pa = _interpolate_pos(motion_by_obj[a], f)
                pb = _interpolate_pos(motion_by_obj[b], f)
                dist = math.hypot(pa[0]-pb[0], pa[1]-pb[1])
                if dist <= threshold:
                    collision_time = f
                    break
            if collision_time is not None:
                outcomes.append({"time": float(collision_time), "kind":"collision",
                                 "entities":[a,b], "value":None, "src":[]})

    # Append exits and sort
    outcomes.extend(exits)
    outcomes = sorted(outcomes, key=lambda o: o["time"])
    return outcomes

