# -------------------------------------------------------------- simulate
import math
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model for CLEVRER physics videos.

    Parameters
    ----------
    doc      : dict
        Original document, only used to read motion logs (via helpers).
    scope    : str
        Scope title (e.g. "Video 10119").
    inputs   : list
        Exogenous events (enter / present / exit) provided by caller.
    params   : dict
        Constant parameters (unused here, kept for compatibility).
    start    : float or None
        Time (frame index) to start simulation. If None, 0.0.
    horizon  : float or None
        End time (frame index). If None, recorded_end of scope.

    Returns
    -------
    list
        List of outcome records (collisions/exits) produced after `start`.
    """
    # Default start / horizon
    start = 0.0 if start is None else float(start)
    horizon_f = recorded_end(doc, scope)
    if horizon is None:
        horizon_f = horizon_f if horizon_f is not None else start
    else:
        horizon_f = float(horizon)

    # ----------------------------------------------------------------------
    #  1. Extract motion logs
    scope_node = node_by_title(doc, scope)
    motion_node = None
    for cid in scope_node.get('children', []):
        child = node_by_id(doc, cid)
        if child['kind'] == 'table' and child['title'].endswith(': Motion log'):
            motion_node = child
            break
    if motion_node is None:
        return []

    # Build per-object sorted list of records
    object_logs = defaultdict(list)   # label -> list of (frame, x, y, vx, vy)
    for _, r in table_rows(motion_node):
        try:
            f = int(r['frame'])
            oid_lbl = r['object'].strip()
            x = float(r['x'])
            y = float(r['y'])
            vx = float(r['vx'])
            vy = float(r['vy'])
        except Exception:
            continue
        object_logs[oid_lbl].append((f, x, y, vx, vy))

    # Sort logs per object
    for lbl in object_logs:
        object_logs[lbl].sort(key=lambda t: t[0])

    # Build mapping from "Object N" to label used in motion logs
    idx_to_label = {}
    for lbl in object_logs:
        if ' ' in lbl:
            idx, _rest = lbl.split(' ', 1)
            idx_to_label[idx] = lbl

    # ----------------------------------------------------------------------
    #  2. Parse input events
    enter_events = defaultdict(list)
    present_events = defaultdict(list)
    exit_events  = defaultdict(list)
    for ev in inputs:
        t = float(ev["time"])
        f = int(round(t))
        entities = ev.get("entities", [])
        if not entities:
            continue
        obj_id = entities[0]  # e.g., "Object 1"
        m = re.match(r"Object (\d+)", obj_id)
        if not m:
            continue
        idx = m.group(1)
        lbl = idx_to_label.get(idx)
        if lbl is None:
            continue
        if ev["kind"] == "enter":
            enter_events[f].append(lbl)
        elif ev["kind"] == "present":
            present_events[f].append(lbl)
        elif ev["kind"] == "exit":
            exit_events[f].append(lbl)

    # ----------------------------------------------------------------------
    #  3. Helper to get last state at or before a frame
    def _state_at(lbl, frame):
        lst = object_logs.get(lbl, [])
        if not lst:
            return None
        best = None
        for rec in lst:
            if rec[0] <= frame:
                best = rec
            else:
                break
        return best[1:] if best else None

    # ----------------------------------------------------------------------
    #  4. Initialise states at start frame
    start_frame = int(math.floor(start))
    current_states = {}
    for lbl in object_logs:
        st = _state_at(lbl, start_frame)
        if st is not None:
            current_states[lbl] = list(st)

    for f in present_events:
        if f <= start_frame:
            for lbl in present_events[f]:
                st = _state_at(lbl, f)
                if st is not None:
                    current_states[lbl] = list(st)

    # ----------------------------------------------------------------------
    #  5. Simulation loop
    EPS = 0.41  # collision distance threshold (inferred from data)
    outcomes = []
    max_frame = int(math.ceil(horizon_f))

    for f in range(start_frame + 1, max_frame + 1):
        # 5a. Objects entering at this frame
        for lbl in enter_events.get(f, []):
            st = _state_at(lbl, f)
            if st is not None:
                current_states[lbl] = list(st)

        # 5b. Update positions for all tracked objects
        for lbl, st in current_states.items():
            st[0] += st[2]  # x += vx
            st[1] += st[3]  # y += vy

        # 5c. Detect collisions
        keys = list(current_states.keys())
        for i in range(len(keys)):
            for j in range(i + 1, len(keys)):
                a, b = keys[i], keys[j]
                sa, sb = current_states[a], current_states[b]
                dx = sa[0] - sb[0]
                dy = sa[1] - sb[1]
                if dx*dx + dy*dy <= EPS*EPS:
                    outcomes.append({
                        "time": float(f),
                        "kind": "collision",
                        "entities": [a, b],
                        "value": None,
                        "src": []
                    })
                    # Simple elastic swap of velocities (equal masses)
                    sa[2], sb[2] = sb[2], sa[2]
                    sa[3], sb[3] = sb[3], sa[3]

        # 5d. Process exits
        for lbl in exit_events.get(f, []):
            current_states.pop(lbl, None)
            outcomes.append({
                "time": float(f),
                "kind": "exit",
                "entities": [lbl],
                "value": None,
                "src": []
            })

    # ----------------------------------------------------------------------
    #  6. Filter outcomes after start
    if start > 0:
        outcomes = [o for o in outcomes if o["time"] > start]
    return outcomes

