import math
from collections import defaultdict
import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model for CLEVRER physics videos.

    Parameters
    ----------
    doc      : dict
        Original document, only used to read motion logs (via helpers).
    scope    : str
        Scope title (e.g. "Video 10119").
    inputs   : list
        Exogenous events (enter / present / exit) provided by caller.
    params   : dict
        Constant parameters (unused here, kept for compatibility).
    start    : float or None
        Time (frame index) to start simulation. If None, 0.0.
    horizon  : float or None
        End time (frame index). If None, recorded_end of scope.

    Returns
    -------
    list
        List of outcome records (collisions/exits) produced after `start`.
    """
    # ----------------------------------------------------------------------
    # 1. Default start / horizon
    start = 0.0 if start is None else float(start)
    horizon_f = recorded_end(doc, scope)
    if horizon is None:
        horizon_f = horizon_f if horizon_f is not None else start
    else:
        horizon_f = float(horizon)

    # ----------------------------------------------------------------------
    # 2. Extract motion logs
    scope_node = node_by_title(doc, scope)
    motion_node = None
    for cid in scope_node.get("children", []):
        child = node_by_id(doc, cid)
        if child["kind"] == "table" and child["title"].endswith(": Motion log"):
            motion_node = child
            break
    if motion_node is None:
        return []

    obj_logs = defaultdict(list)
    for _, r in table_rows(motion_node):
        try:
            f = int(r["frame"])
            lbl = r["object"].strip()
            x, y = float(r["x"]), float(r["y"])
            vx, vy = float(r["vx"]), float(r["vy"])
        except Exception:
            continue
        obj_logs[lbl].append((f, x, y, vx, vy))
    for lbl in obj_logs:
        obj_logs[lbl].sort(key=lambda t: t[0])

    # Mapping: Motion log label -> "Object N" and reverse
    lbl_to_objid = {}
    objid_to_lbl = {}
    for lbl in obj_logs:
        m = re.match(r"(\d+)", lbl)
        if m:
            idx = m.group(1)
            objid = f"Object {idx}"
            lbl_to_objid[lbl] = objid
            objid_to_lbl[objid] = lbl

    # ----------------------------------------------------------------------
    # 3. Parse inputs
    enter_events = defaultdict(list)
    present_events = defaultdict(list)
    exit_events = defaultdict(list)

    for ev in inputs:
        t = float(ev["time"])
        f = int(round(t))
        entities = ev.get("entities", [])
        if not entities:
            continue
        objid = entities[0]
        lbl = objid_to_lbl.get(objid)
        if lbl is None:
            continue
        if ev["kind"] == "enter":
            enter_events[f].append(lbl)
        elif ev["kind"] == "present":
            present_events[f].append(lbl)
        elif ev["kind"] == "exit":
            exit_events[f].append(lbl)

    # ----------------------------------------------------------------------
    # 4. Helper: last state <= frame
    def _state_at(lbl, frame):
        lst = obj_logs.get(lbl, [])
        if not lst:
            return None
        best = None
        for rec in lst:
            if rec[0] <= frame:
                best = rec
            else:
                break
        return best[1:] if best else None

    # ----------------------------------------------------------------------
    # 5. Initialise state at `start_frame`
    start_frame = int(math.floor(start))
    cur_states = {}
    # All objects that have entered before or at start_frame
    for f in enter_events:
        if f <= start_frame:
            for lbl in enter_events[f]:
                st = _state_at(lbl, f)
                if st is not None:
                    cur_states[lbl] = list(st)
    # Objects present at frame 0 or any earlier present events
    for f in present_events:
        if f <= start_frame:
            for lbl in present_events[f]:
                st = _state_at(lbl, f)
                if st is not None:
                    cur_states[lbl] = list(st)

    # ----------------------------------------------------------------------
    # 6. Simulation loop
    EPS = 0.41   # collision distance threshold (from observation)
    outcomes = []
    max_frame = int(math.ceil(horizon_f))

    for f in range(start_frame + 1, max_frame + 1):
        # a) Entering objects at this frame
        for lbl in enter_events.get(f, []):
            st = _state_at(lbl, f)
            if st is not None:
                cur_states[lbl] = list(st)

        # b) Update positions
        for lbl, st in cur_states.items():
            st[0] += st[2]   # x += vx
            st[1] += st[3]   # y += vy

        # c) Collision detection
        keys = list(cur_states.keys())
        for i in range(len(keys)):
            for j in range(i + 1, len(keys)):
                a, b = keys[i], keys[j]
                sa, sb = cur_states[a], cur_states[b]
                dx = sa[0] - sb[0]
                dy = sa[1] - sb[1]
                if dx * dx + dy * dy <= EPS * EPS:
                    outcomes.append({
                        "time": float(f),
                        "kind": "collision",
                        "entities": [lbl_to_objid[a], lbl_to_objid[b]],
                        "value": None,
                        "src": []
                    })
                    # Exchange velocities (simple equal‑mass elastic swap)
                    sa[2], sb[2] = sb[2], sa[2]
                    sa[3], sb[3] = sb[3], sa[3]

        # d) Exit events
        for lbl in exit_events.get(f, []):
            cur_states.pop(lbl, None)
            outcomes.append({
                "time": float(f),
                "kind": "exit",
                "entities": [lbl_to_objid[lbl]],
                "value": None,
                "src": []
            })

    # ----------------------------------------------------------------------
    # 7. Trim outcomes to strictly after `start`
    if start > 0:
        outcomes = [o for o in outcomes if o["time"] > start]
    return outcomes

