import math
from collections import defaultdict
import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward physics model for CLEVRER videos that respects the provided
    `inputs` (enter / present / exit events).  The model uses recorded
    motion logs only to initialise states and to obtain the first
    velocity/position for newly-entering objects.  Afterwards it runs
    a deterministic simulation (constant velocity until an outcome).
    """
    # ----------------------------------------------------------------------
    # 1. Normalise arguments
    start = 0.0 if start is None else float(start)
    horizon_f = recorded_end(doc, scope)
    if horizon is None:
        horizon_f = horizon_f if horizon_f is not None else start
    else:
        horizon_f = float(horizon)
    max_frame = int(math.ceil(horizon_f))

    # ----------------------------------------------------------------------
    # 2. Extract motion logs per label
    scope_node = node_by_title(doc, scope)
    motion_node = None
    for cid in scope_node.get("children", []):
        child = node_by_id(doc, cid)
        if child["kind"] == "table" and child["title"].endswith(": Motion log"):
            motion_node = child
            break
    if motion_node is None:
        return []

    # For each label store sorted list of (frame, x, y, vx, vy)
    obj_logs = defaultdict(list)
    lbl_to_objid = {}
    objid_to_lbl = {}
    for _, r in table_rows(motion_node):
        try:
            f = int(r["frame"])
            lbl = r["object"].strip()
            x, y = float(r["x"]), float(r["y"])
            vx, vy = float(r["vx"]), float(r["vy"])
        except Exception:
            continue
        obj_logs[lbl].append((f, x, y, vx, vy))

    for lbl in obj_logs:
        obj_logs[lbl].sort(key=lambda t: t[0])

    # Build label <-> Object N mapping
    for lbl in obj_logs:
        m = re.match(r"(\d+)", lbl)
        if m:
            idx = m.group(1)
            objid = f"Object {idx}"
            lbl_to_objid[lbl] = objid
            objid_to_lbl[objid] = lbl

    # ----------------------------------------------------------------------
    # 3. Helper: first record with frame >= target
    def _first_after(lbl, target):
        lst = obj_logs.get(lbl, [])
        for rec in lst:
            if rec[0] >= target:
                return rec
        return None

    # ----------------------------------------------------------------------
    # 4. Parse input events
    enter_events = defaultdict(list)
    present_events = defaultdict(list)
    exit_events = defaultdict(list)
    for ev in inputs:
        f = int(round(float(ev["time"])))
        entities = ev.get("entities", [])
        if not entities:
            continue
        objid = entities[0]
        lbl = objid_to_lbl.get(objid)
        if lbl is None:
            continue
        kind = ev["kind"]
        if kind == "enter":
            enter_events[f].append(lbl)
        elif kind == "present":
            present_events[f].append(lbl)
        elif kind == "exit":
            exit_events[f].append(lbl)

    # ----------------------------------------------------------------------
    # 5. Initialise state at `start_frame`
    start_frame = int(math.floor(start))
    cur_states = {}  # lbl -> [x, y, vx, vy]

    # Objects present at or before start_frame
    for f in present_events:
        if f <= start_frame:
            for lbl in present_events[f]:
                rec = _first_after(lbl, f)
                if rec is not None:
                    cur_states[lbl] = list(rec[1:])  # [x,y,vx,vy]

    # Objects that entered before or at start_frame
    for f in enter_events:
        if f <= start_frame:
            for lbl in enter_events[f]:
                rec = _first_after(lbl, f)
                if rec is not None:
                    cur_states[lbl] = list(rec[1:])

    # ----------------------------------------------------------------------
    # 6. Simulation loop from start_frame+1 to max_frame
    EPS = 0.41  # collision distance threshold
    outcomes = []

    for f in range(start_frame + 1, max_frame + 1):
        # 6a. Process exit events first
        for lbl in exit_events.get(f, []):
            cur_states.pop(lbl, None)
            outcomes.append({
                "time": float(f),
                "kind": "exit",
                "entities": [lbl_to_objid[lbl]],
                "value": None,
                "src": []
            })

        # 6b. Process enter events
        for lbl in enter_events.get(f, []):
            rec = _first_after(lbl, f)
            if rec is not None:
                cur_states[lbl] = list(rec[1:])

        # 6c. Advance all objects by their velocity
        for lbl, st in cur_states.items():
            st[0] += st[2]   # x += vx
            st[1] += st[3]   # y += vy

        # 6d. Collision detection
        keys = list(cur_states.keys())
        for i in range(len(keys)):
            for j in range(i + 1, len(keys)):
                a, b = keys[i], keys[j]
                ta, tb = cur_states[a], cur_states[b]
                dx = ta[0] - tb[0]
                dy = ta[1] - tb[1]
                if dx * dx + dy * dy <= EPS * EPS:
                    outcomes.append({
                        "time": float(f),
                        "kind": "collision",
                        "entities": [lbl_to_objid[a], lbl_to_objid[b]],
                        "value": None,
                        "src": []
                    })
                    # Simple elastic swap of velocities for equal masses
                    ta[2], tb[2] = tb[2], ta[2]
                    ta[3], tb[3] = tb[3], ta[3]

    # ----------------------------------------------------------------------
    # 7. Trim outcomes before the requested start time
    if start > 0:
        outcomes = [o for o in outcomes if o["time"] > start]
    return outcomes

