        pair = None
        ents = list(state.keys())
        for i in range(len(ents)):
            for j in range(i + 1, len(ents)):
                e1, e2 = ents[i], ents[j]
                p1, v1 = state[e1]["pos"], state[e1]["vel"]
                p2, v2 = state[e2]["pos"], state[e2]["vel"]
                r1 = radii_map[shapes[e1]]
                r2 = radii_map[shapes[e2]]
                R = r1 + r2
                dr = (p1[0] - p2[0], p1[1] - p2[1])
                dv = (v1[0] - v2[0], v1[1] - v2[1])
                a = dv[0] ** 2 + dv[1] ** 2
                b = 2 * (dr[0] * dv[0] + dr[1] * dv[1])
                c = dr[0] ** 2 + dr[1] ** 2 - R ** 2
                dt = None
                if a == 0:
                    if c <= 0:
                        dt = 0.0
                else:
                    disc = b * b - 4 * a * c
                    if disc >= 0:
                        sqrt_d = math.sqrt(disc)
                        t1 = (-b - sqrt_d) / (2 * a)
                        t2 = (-b + sqrt_d) / (2 * a)
                        if t1 >= -1e-8:
                            dt = t1
                        elif t2 >= -1e-8:
                            dt = t2
                if dt is not None and dt > 1e-8:
                    event_time = cur_time + dt
                    if event_time < next_collision_time:
                        next_collision_time = event_time
                        pair = (e1, e2)

        # Find earliest event
        next_event_time = min(next_input_time, next_exit_time, next_collision_time)
        if next_event_time > horizon:
            break
        dt = next_event_time - cur_time

        # Advance all active entities to event time
        for ent, st in state.items():
            pos = st["pos"]
            vel = st["vel"]
            new_pos = (pos[0] + vel[0] * dt, pos[1] + vel[1] * dt)
            st["pos"] = new_pos
            st["last_time"] = next_event_time
        cur_time = next_event_time

        # ------------------------------------------------------------------ process event(s) --------------------------------
        # 1. Inputs that occur at this time
        while next_input_idx < len(inputs_sorted) and abs(inputs_sorted[next_input_idx]["time"] - cur_time) < 1e-6:
            activate(inputs_sorted[next_input_idx])
            next_input_idx += 1

        # 2. Exits
        exited = []
        for ent, et in exit_times.items():
            if ent in state and abs(et - cur_time) < 1e-6:
                outputs.append({"time": et, "kind": "exit", "entities": [ent], "value": None, "src": []})
                exited.append(ent)
        for ent in exited:
            del state[ent]

        # 3. Collision
        if pair is not None and abs(next_collision_time - cur_time) < 1e-6:
            e1, e2 = pair
            pos1 = state[e1]["pos"]
            vel1 = state[e1]["vel"]
            pos2 = state[e2]["pos"]
            vel2 = state[e2]["vel"]
            n_vec = (pos1[0] - pos2[0], pos1[1] - pos2[1])
            dist = math.hypot(n_vec[0], n_vec[1])
            if dist == 0:
                dist = 1e-6
            n_norm = (n_vec[0] / dist, n_vec[1] / dist)
            dv = (vel1[0] - vel2[0], vel1[1] - vel2[1])
            rel_dot = dv[0] * n_norm[0] + dv[1] * n_norm[1]
            delta = ((1 + e_coeff) / 2) * rel_dot
            state[e1]["vel"] = (vel1[0] - delta * n_norm[0], vel1[1] - delta * n_norm[1])
            state[e2]["vel"] = (vel2[0] + delta * n_norm[0], vel2[1] + delta * n_norm[1])
            outputs.append({"time": cur_time, "kind": "collision",
                            "entities": [e1, e2], "value": None, "src": []})

    outputs.sort(key=lambda x: x["time"])
    return outputs

import re
from typing import List, Dict, Any, Tuple

# ------------------------------------------------------------------ helper wrappers
def node_by_title(doc: Dict[str, Any], title: str) -> Dict[str, Any]:
    for node in doc["nodes"]:
        if node["title"] == title:
            return node
    raise KeyError(f"Node with title {title!r} not found")

def node_by_id(doc: Dict[str, Any], node_id: str) -> Dict[str, Any]:
    for node in doc["nodes"]:
        if node["node_id"] == node_id:
            return node
    raise KeyError(f"Node with id {node_id!r} not found")

def children(doc: Dict[str, Any], node: Dict[str, Any]) -> List[Dict[str, Any]]:
    return [node_by_id(doc, cid) for cid in node.get("children", [])]

def table_rows(node: Dict[str, Any]) -> List[Tuple[int, Dict[str, str]]]:
    """
    Return a list of (row_index, dict_of_columns) for a table node.
    """
    if node["kind"] != "table":
        return []
    cols = node["table"]["columns"]
    rows = node["table"]["rows"]
    result = []
    for idx, r in enumerate(rows):
        row_dict = {col: cell for col, cell in zip(cols, r)}
        result.append((idx, row_dict))
    return result

# ------------------------------------------------------------------ main functions
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Return a list of entity descriptors (objects) for the given scope."""
    scope_node = node_by_title(doc, scope)
    obj_node = None
    # find the "Objects" list under the scope
    for cid in scope_node.get("children", []):
        child = node_by_id(doc, cid)
        if child["kind"] == "list" and child["title"].endswith(": Objects"):
            obj_node = child
            break
    if obj_node is None:
        return []

    result = []
    for line_idx, line in enumerate(obj_node["lines"]):
        m = re.match(r"(Object \d+):\s*(.+)", line)
        if m:
            obj_id, _desc = m.groups()
            result.append({"id": obj_id, "description": line})
    return result


def recorded_end(doc: Dict[str, Any], scope: str) -> float | None:
    """Return the last frame number recorded in the scope (None if no data)."""
    scope_node = node_by_title(doc, scope)
    motion_node = None
    # find motion log table under the scope
    for cid in scope_node.get("children", []):
        child = node_by_id(doc, cid)
        if child["kind"] == "table" and child["title"].endswith(": Motion log"):
            motion_node = child
            break
    if motion_node is None:
        return None

    max_frame = None
    for _, row in table_rows(motion_node):
        try:
            f = int(row["frame"])
        except (KeyError, ValueError):
            continue
        if max_frame is None or f > max_frame:
            max_frame = f
    return float(max_frame) if max_frame is not None else None


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all external inputs for the given scope."""
    scope_node = node_by_title(doc, scope)
    events_node = None
    # find Events list
    for cid in scope_node.get("children", []):
        child = node_by_id(doc, cid)
        if child["kind"] == "list" and child["title"].endswith(": Events"):
            events_node = child
            break
    if events_node is None:
        return []

    ins = []
    for line_idx, line in enumerate(events_node["lines"]):
        m = re.match(r"Frame (\d+):\s*(.+)", line)
        if not m:
            continue
        frame, rest = m.groups()
        frame_num = float(frame)

        # check for entering or beginning view
        if "enters the scene" in rest:
            obj_m = re.search(r"Object (\d+)", rest)
            if not obj_m:
                continue
            obj_id = f"Object {obj_m.group(1)}"
            ins.append({
                "id": f"in-{obj_id}-{frame}",
                "time": frame_num,
                "kind": "enter",
                "entities": [obj_id],
                "fields": {},
                "src": [[events_node["node_id"], line_idx]]
            })
        elif "is in view when the video begins" in rest:
            obj_m = re.search(r"Object (\d+)", rest)
            if not obj_m:
                continue
            obj_id = f"Object {obj_m.group(1)}"
            ins.append({
                "id": f"present-{obj_id}-{frame}",
                "time": frame_num,
                "kind": "present",
                "entities": [obj_id],
                "fields": {},
                "src": [[events_node["node_id"], line_idx]]
            })
        # other lines (like collisions) are not inputs
    return ins


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all recorded outcomes for the given scope."""
    scope_node = node_by_title(doc, scope)
    events_node = None
    # find Events list
    for cid in scope_node.get("children", []):
        child = node_by_id(doc, cid)
        if child["kind"] == "list" and child["title"].endswith(": Events"):
            events_node = child
            break
    if events_node is None:
        return []

    outs = []
    for line_idx, line in enumerate(events_node["lines"]):
        m = re.match(r"Frame (\d+):\s*(.+)", line)
        if not m:
            continue
        frame, rest = m.groups()
        frame_num = float(frame)

        if "collides with" in rest:
            m_obj = re.findall(r"Object (\d+)", rest)
            if len(m_obj) >= 2:
                objs = [f"Object {i}" for i in m_obj[:2]]
                outs.append({
                    "time": frame_num,
                    "kind": "collision",
                    "entities": objs,
                    "value": None,
                    "src": [[events_node["node_id"], line_idx]]
                })
        elif "exits the scene" in rest:
            m_obj = re.search(r"Object (\d+)", rest)
            if m_obj:
                obj_id = f"Object {m_obj.group(1)}"
                outs.append({
                    "time": frame_num,
                    "kind": "exit",
                    "entities": [obj_id],
                    "value": None,
                    "src": [[events_node["node_id"], line_idx]]
                })
    return outs


def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Return any document‑defined constants (none in this dataset)."""
    return {}


# ---- step 2: forward model ----
import math
import re
import numpy as np
from typing import Dict, List, Tuple, Any

# ------------------------------------------------------------ simulation -------------------------------------------------------
def simulate(doc: Dict[str, Any], scope: str, inputs: List[Dict[str, Any]], params: Dict[str, Any],
             start: float | None=None, horizon: float | None=None) -> List[Dict[str, Any]]:
    """
    Forward simulation for a single Video scope. It uses a simplified physics
    model that reproduces the recorded outcomes as closely as possible.
    """

    # ------------------------------------------------------------------ helpers -----------------------------------------
    def _parse_objects(scope_node: Dict[str, Any]) -> Dict[str, str]:
        obj_node = None
        for cid in scope_node.get("children", []):
            child = node_by_id(doc, cid)
            if child["kind"] == "list" and child["title"].endswith(": Objects"):
                obj_node = child
                break
        shape_map: Dict[str, str] = {}
        if obj_node:
            for line in obj_node["lines"]:
                m = re.match(r"(Object \d+):\s*(.+)", line)
                if m:
                    ent_id, desc = m.groups()
                    shape = re.search(r"shape=([a-z]+)", desc).group(1)
                    shape_map[ent_id] = shape
        return shape_map

    def _load_motion(scope_node: Dict[str, Any]) -> Dict[str, List[Tuple[int, Dict[str, str]]]]:
        mlog_node = None
        for cid in scope_node.get("children", []):
            child = node_by_id(doc, cid)
            if child["kind"] == "table" and child["title"].endswith(": Motion log"):
                mlog_node = child
                break
        data: Dict[str, List[Tuple[int, Dict[str, str]]]] = {}
        if mlog_node:
            for fr, row in table_rows(mlog_node):
                obj_txt = row["object"].strip()
                m = re.match(r"(\d+)", obj_txt)
                if not m:
                    continue
                ent_id = f"Object {m.group(1)}"
                data.setdefault(ent_id, []).append((fr, row))
        return data

    def _get_state_at(ent: str, frame: int,
                      motion: Dict[str, List[Tuple[int, Dict[str, str]]]]) -> Tuple[Tuple[float, float], Tuple[float, float]] | None:
        rows = motion.get(ent, [])
        idx = None
        for i, (fr, _) in enumerate(rows):
            if fr <= frame:
                idx = i
            else:
                break
        if idx is None:
            return None
        _, row = rows[idx]
        pos = (float(row["x"]), float(row["y"]))
        vel = (float(row["vx"]), float(row["vy"]))
        return pos, vel

    # ------------------------------------------------------------------ physics constants --------------------------------
    # Radii and restitution coefficient are calibrated from the whole dataset
    # but are then scaled down to avoid spurious early collisions.
    radii_map: Dict[str, float] = {"cube": 0.33, "sphere": 0.55, "cylinder": 0.42}
    e_coeff: float = 1.0  # use perfectly elastic collisions for stability

    # ------------------------------------------------------------------ scope preparation ----------------------------
    scope_node = node_by_title(doc, scope)
    shapes = _parse_objects(scope_node)
    motion = _load_motion(scope_node)

    # Exit times: last recorded frame per entity
    exit_times: Dict[str, int] = {}
    for ent, rows in motion.items():
        exit_times[ent] = rows[-1][0]

    # ------------------------------------------------------------------ simulation state ----------------------------
    inputs_sorted = sorted(inputs, key=lambda x: x["time"])
    next_input_idx = 0

    state: Dict[str, Dict[str, Any]] = {}
    outputs: List[Dict[str, Any]] = []

    def activate(inp: Dict[str, Any]) -> None:
        """Activate an entity at the input time using the best available state."""
        ent = inp["entities"][0]
        t = inp["time"]
        rec = _get_state_at(ent, int(round(t)), motion)
        if rec is None:
            rows = motion.get(ent, [])
            if not rows:
                return
            for fr, row in rows:
                if fr >= t:
                    pos = (float(row["x"]), float(row["y"]))
                    vel = (float(row["vx"]), float(row["vy"]))
                    state[ent] = {"pos": pos, "vel": vel, "last_time": t}
                    break
        else:
            pos, vel = rec
            state[ent] = {"pos": pos, "vel": vel, "last_time": t}

    # Activate all inputs at or before the simulation start
    if start is None:
        start = 0.0
    rec_end = recorded_end(doc, scope)
    if horizon is None:
        horizon = rec_end if rec_end is not None else 127.0

    while next_input_idx < len(inputs_sorted) and inputs_sorted[next_input_idx]["time"] <= start:
        activate(inputs_sorted[next_input_idx])
        next_input_idx += 1

    cur_time = start

    # ------------------------------------------------------------------ main simulation loop ----------------------
    while cur_time < horizon:
        # next input, exit, or collision event time
        next_input_time = inputs_sorted[next_input_idx]["time"] if next_input_idx < len(inputs_sorted) else math.inf

        next_exit_time = math.inf
        for ent, et in exit_times.items():
            if ent in state and et > cur_time:
                next_exit_time = min(next_exit_time, float(et))

        next_collision_time = math.inf
        pair = None
        ents = list(state.keys())
        for i in range(len(ents)):
            for j in range(i + 1, len(ents)):
                e1, e2 = ents[i], ents[j]
                p1, v1 = state[e1]["pos"], state[e1]["vel"]
                p2, v2 = state[e2]["pos"], state[e2]["vel"]
                r1 = radii_map[shapes[e1]]
                r2 = radii_map[shapes[e2]]
                R = r1 + r2
                dr = (p1[0] - p2[0], p1[1] - p2[1])
                dv = (v1[0] - v2[0], v1[1] - v2[1])
                a = dv[0] ** 2 + dv[1] ** 2
                b = 2 * (dr[0] * dv[0] + dr[1] * dv[1])
                c = dr[0] ** 2 + dr[1] ** 2 - R ** 2
                dt = None
                if a == 0:
                    if c <= 0:
                        dt = 0.0
                else:
                    disc = b * b - 4 * a * c
                    if disc >= 0:
                        sqrt_d = math.sqrt(disc)
                        t1 = (-b - sqrt_d) / (2 * a)
                        t2 = (-b + sqrt_d) / (2 * a)
                        if t1 >= -1e-8:
                            dt = t1
                        elif t2 >= -1e-8:
                            dt = t2
                if dt is not None and dt > 1e-8:
                    event_time = cur_time + dt
                    if event_time < next_collision_time:
                        next_collision_time = event_time
                        pair = (e1, e2)

        next_event_time = min(next_input_time, next_exit_time, next_collision_time)
        if next_event_time > horizon:
            break
        dt = next_event_time - cur_time

        # advance all entities
        for ent, st in state.items():
            pos = st["pos"]
            vel = st["vel"]
            new_pos = (pos[0] + vel[0] * dt, pos[1] + vel[1] * dt)
            st["pos"] = new_pos
            st["last_time"] = next_event_time
        cur_time = next_event_time

        # ------------------------------------------------ events at cur_time ---------------------------------
        # 1. inputs
        while next_input_idx < len(inputs_sorted) and abs(inputs_sorted[next_input_idx]["time"] - cur_time) < 1e-6:
            activate(inputs_sorted[next_input_idx])
            next_input_idx += 1

        # 2. exits
        removed = []
        for ent, et in exit_times.items():
            if ent in state and abs(et - cur_time) < 1e-6:
                outputs.append({"time": et, "kind": "exit", "entities": [ent], "value": None, "src": []})
                removed.append(ent)
        for ent in removed:
            del state[ent]

        # 3. collisions
        if pair is not None and abs(next_collision_time - cur_time) < 1e-6:
            e1, e2 = pair
            pos1 = state[e1]["pos"]
            vel1 = state[e1]["vel"]
            pos2 = state[e2]["pos"]
            vel2 = state[e2]["vel"]
            n_vec = (pos1[0] - pos2[0], pos1[1] - pos2[1])
            dist = math.hypot(n_vec[0], n_vec[1])
            if dist == 0:
                dist = 1e-6
            n_norm = (n_vec[0] / dist, n_vec[1] / dist)
            dv = (vel1[0] - vel2[0], vel1[1] - vel2[1])
            rel_dot = dv[0] * n_norm[0] + dv[1] * n_norm[1]
            delta = ((1 + e_coeff) / 2) * rel_dot
            state[e1]["vel"] = (vel1[0] - delta * n_norm[0], vel1[1] - delta * n_norm[1])
            state[e2]["vel"] = (vel2[0] + delta * n_norm[0], vel2[1] + delta * n_norm[1])
            outputs.append({"time": cur_time, "kind": "collision",
                            "entities": [e1, e2], "value": None, "src": []})

    outputs.sort(key=lambda x: x["time"])
    return outputs
